import { isZh, type Lang } from "@/lib/i18n";

export type ProductRichDetail = {
  html: string;
  htmlEn?: string;
};

export function getProductRichDetailHtml(detail: ProductRichDetail | undefined, lang: Lang) {
  if (!detail) {
    return undefined;
  }

  return isZh(lang) ? detail.html : detail.htmlEn;
}

